import os
import csv
from pathlib import Path
from collections import defaultdict

NODE_FLOW_DIR = Path(os.environ["NODE_FLOW_DIR"])

files = ["20191106_node.csv", "20191107_node.csv", "20191118_node.csv"]
stations = ["靖边站", "南通站"]

# per-file, per-station absolute flow sums
per_file = {f: {s: 0.0 for s in stations} for f in files}

for fname in files:
    csv_path = NODE_FLOW_DIR / fname
    with open(csv_path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            station = row.get("站点名称", "")
            if station in stations:
                flow_str = row.get("计算流量", "")
                try:
                    flow = float(flow_str)
                except (ValueError, TypeError):
                    continue
                per_file[fname][station] += abs(flow)

print("=== Per-file absolute flows ===")
for fname in files:
    for s in stations:
        print(f"  {s} - {fname}: {per_file[fname][s]:.3f}")

# cumulative totals
totals = {s: sum(per_file[f][s] for f in files) for s in stations}
print("\n=== Cumulative totals (all 3 files) ===")
for s in stations:
    print(f"  {s}: {totals[s]:.3f}")

# identify peak day (max total across both stations)
day_totals = {}
for fname in files:
    day_totals[fname] = sum(per_file[fname][s] for s in stations)
print("\n=== Daily totals ===")
for fname in files:
    print(f"  {fname}: {day_totals[fname]:.3f}")

peak_day = max(day_totals, key=day_totals.get)
print(f"\nPeak day: {peak_day} (total {day_totals[peak_day]:.3f})")

# exclude peak day
excluded_totals = {s: sum(per_file[f][s] for f in files if f != peak_day) for s in stations}
print("\n=== Totals excluding peak day ===")
for s in stations:
    print(f"  {s}: {excluded_totals[s]:.3f}")

print("\n=== Ranking ===")
print(f"Full window: {max(stations, key=totals.get)} > {min(stations, key=totals.get)}")
print(f"Excluding peak: {max(stations, key=excluded_totals.get)} > {min(stations, key=excluded_totals.get)}")

